cd /workspace && python3 -c "
import os
print('pgrp', os.getpgrp(), 'pid', os.getpid())
try:
    os.killpg(os.getpgrp(), 0); print('killpg ok')
except OSError as e: print('killpg fail', e)
try:
    os.kill(os.getpid(), 0); print('kill self ok')
except OSError as e: print('kill self fail', e)
"; cat /proc/self/status | grep -i seccomp; ls /proc/self/ | head
